 static Exception Invalid(){return DesktopTrustKeyParentBasisSource.Invalid();}
 internal static Dictionary<string,object> Empty(){return new Dictionary<string,object>{{"schemaVersion",1},{"purpose","DESKTOP_TRUST_BINDINGS"},{"sequence",1},{"previousHash",null},{"catalogueHighWater",null},{"rows",new object[0]}};}
