 internal static void Validate(Dictionary<string,object> c){DesktopTrustKeyHostSource.Exact(c,"schemaVersion,purpose,sequence,previousHash,catalogueHighWater,rows");if(DesktopTrustKeyHostSource.Positive(c["schemaVersion"])!=1||DesktopTrustKeyHostSource.Text(c,"purpose")!="DESKTOP_TRUST_BINDINGS")throw Invalid();long sequence=DesktopTrustKeyHostSource.Positive(c["sequence"]);if(sequence==1?c["previousHash"]!=null:!DesktopTrustKeyHostSource.IsHash(c["previousHash"]))throw Invalid();HighWater(c["catalogueHighWater"]);
