 }
 internal static void HighWater(object raw){if(raw==null)return;var value=DesktopTrustKeyHostSource.Map(raw);DesktopTrustKeyHostSource.Exact(value,"profileId,sequence,releaseRef");DesktopTrustKeyHostSource.Id(value,"profileId");long sequence=DesktopTrustKeyHostSource.Positive(value["sequence"]);var r=DesktopTrustKeyHostSource.Ref(value["releaseRef"]);if(DesktopTrustKeyHostSource.Positive(r["version"])!=sequence)throw Invalid();}
 internal static void Record(Dictionary<string,object> r){DesktopTrustKeyHostSource.Exact(r,"schemaVersion,purpose,bindingId,revision,previousHash,attemptId,origin,label,pendingKeyId,projectIdHint,projectId,key,registration,credential,profile,state,uncertainStep,createdAt,updatedAt");if(Encoding.UTF8.GetByteCount(DesktopTrustKeyHostSource.Canonical(r,0))>16384||DesktopTrustKeyHostSource.Positive(r["schemaVersion"])!=1||DesktopTrustKeyHostSource.Text(r,"purpose")!="DESKTOP_TRUST_KEY_BINDING")throw Invalid();foreach(string key in new[]{"bindingId","attemptId","pendingKeyId"})DesktopTrustKeyHostSource.Id(r,key);long revision=DesktopTrustKeyHostSource.Positive(r["revision"]);if(revision==1?r["previousHash"]!=null:!DesktopTrustKeyHostSource.IsHash(r["previousHash"]))throw Invalid();string origin=DesktopTrustKeyHostSource.Text(r,"origin"),label=DesktopTrustKeyHostSource.Text(r,"label");Uri u;if(origin.Length>2048||!Uri.TryCreate(origin,UriKind.Absolute,out u)||u.Scheme!="https"||u.UserInfo!=""||u.GetLeftPart(UriPartial.Authority)!=origin||label.Length<1||label.Length>200)throw Invalid();if(DesktopTrustKeyHostSource.Time(r,"updatedAt")<DesktopTrustKeyHostSource.Time(r,"createdAt"))throw Invalid();string state=DesktopTrustKeyHostSource.Text(r,"state");
