 internal Dictionary<string,object> Read(){if(busy)throw new DesktopTrustKeyStoreUnknownException();RequireSettled();var current=ReadOwned();RequireSettled();return current;}
 // 일반 Read는 전후 sidecar 검사를 감싼다. Append의 자기 lock/next 안에서는 이 private 원문 경로만 쓴다.
 Dictionary<string,object> ReadOwned(){
  byte[] current=null,previous=null;
  try{
   check();current=io.Read("bindings.v1",Maximum);if(current!=null)observedContainer=true;check();
   previous=io.Read("bindings.v1.previous",Maximum);if(previous!=null)observedContainer=true;check();
   if(current==null){if(observedContainer){unknown=true;throw new DesktopTrustKeyStoreUnknownException();}return null;}
   var c=Decode(current);
   if(DesktopTrustKeyHostSource.Positive(c["sequence"])>1){var p=Decode(previous);if(p==null||DesktopTrustKeyHostSource.Positive(p["sequence"])+1!=DesktopTrustKeyHostSource.Positive(c["sequence"])||!Equals(c["previousHash"],DesktopTrustKeyHostSource.Hash(Encoding.UTF8.GetBytes(DesktopTrustKeyHostSource.Canonical(p,0)))))throw Invalid();}else if(previous!=null)throw Invalid();
   return c;
  }finally{if(current!=null)Array.Clear(current,0,current.Length);if(previous!=null)Array.Clear(previous,0,previous.Length);}
 }
 internal Dictionary<string,object> Append(string expectedHash,long expectedSequence,Dictionary<string,object> record,object highWater){if(busy)throw Invalid();RequireSettled();record=DesktopTrustKeyHostSource.Parse(Encoding.UTF8.GetBytes(DesktopTrustKeyHostSource.Canonical(record,0)),false);if(highWater!=null)highWater=DesktopTrustKeyHostSource.Parse(Encoding.UTF8.GetBytes(DesktopTrustKeyHostSource.Canonical(highWater,0)),false);busy=true;try{check();using(io.Lock()){check();var old=ReadOwned();string oldHash=old==null?null:DesktopTrustKeyHostSource.Hash(Encoding.UTF8.GetBytes(DesktopTrustKeyHostSource.Canonical(old,0)));long sequence=old==null?0:DesktopTrustKeyHostSource.Positive(old["sequence"]);if(sequence!=expectedSequence||oldHash!=expectedHash)throw Invalid();Record(record);HighWater(highWater);var rows=old==null?new List<object>():Rows(old).ToList();if(rows.Count>=1024)throw Invalid();var existing=rows.Select(DesktopTrustKeyHostSource.Map).Where(r=>Equals(r["bindingId"],record["bindingId"])).LastOrDefault();if(existing==null){if(DesktopTrustKeyHostSource.Text(record,"state")!="KEY_PENDING"||DesktopTrustKeyHostSource.Positive(record["revision"])!=1)throw Invalid();}else{string before=DesktopTrustKeyHostSource.Text(existing,"state"),after=DesktopTrustKeyHostSource.Text(record,"state");if(before=="KEY_PENDING"&&after!="KEY_READY"&&after!="UNKNOWN"||before=="KEY_READY"&&after!="UNKNOWN"||before=="UNKNOWN")throw Invalid();}if(old!=null&&old["catalogueHighWater"]!=null){var h=DesktopTrustKeyHostSource.Map(old["catalogueHighWater"]),n=DesktopTrustKeyHostSource.Map(highWater);if(!Equals(h["profileId"],n["profileId"])||DesktopTrustKeyHostSource.Positive(n["sequence"])<DesktopTrustKeyHostSource.Positive(h["sequence"])||Equals(n["sequence"],h["sequence"])&&DesktopTrustKeyHostSource.Canonical(n,0)!=DesktopTrustKeyHostSource.Canonical(h,0))throw Invalid();}rows.Add(record);var next=new Dictionary<string,object>{{"schemaVersion",1},{"purpose","DESKTOP_TRUST_BINDINGS"},{"sequence",sequence+1},{"previousHash",oldHash},{"catalogueHighWater",highWater},{"rows",rows.ToArray()}};Validate(next);string expectedText=DesktopTrustKeyHostSource.Canonical(next,0);byte[] plain=Encoding.UTF8.GetBytes(expectedText),cipher=null;try{if(plain.Length>Maximum)throw Invalid();cipher=io.Protect((byte[])plain.Clone());check();if(cipher==null||cipher.Length<1||cipher.Length>Maximum)throw Invalid();io.WriteNext((byte[])cipher.Clone());check();var observed=io.Read("bindings.v1.next",Maximum);check();try{var decoded=Decode(observed);if(decoded==null||DesktopTrustKeyHostSource.Canonical(decoded,0)!=expectedText)throw Invalid();}finally{if(observed!=null)Array.Clear(observed,0,observed.Length);}var again=ReadOwned();if((again==null?null:DesktopTrustKeyHostSource.Hash(Encoding.UTF8.GetBytes(DesktopTrustKeyHostSource.Canonical(again,0))))!=oldHash)throw Invalid();check();io.Replace(oldHash,old==null);check();var saved=ReadOwned();if(saved==null||DesktopTrustKeyHostSource.Canonical(saved,0)!=expectedText)throw Invalid();return saved;}catch{unknown=true;throw new DesktopTrustKeyStoreUnknownException();}finally{Array.Clear(plain,0,plain.Length);if(cipher!=null)Array.Clear(cipher,0,cipher.Length);}}}finally{busy=false;}}
}
internal sealed class WindowsDesktopTrustKeyBindingKernel:DesktopTrustKeyBindingKernel {
 [StructLayout(LayoutKind.Sequential)]struct FT{internal uint Low,High;}
 [StructLayout(LayoutKind.Sequential)]struct FI{internal uint Attributes;internal FT Created,Accessed,Written;internal uint Volume,SizeHigh,SizeLow,Links,IndexHigh,IndexLow;}
 [DllImport("kernel32.dll",SetLastError=true)]static extern bool GetFileInformationByHandle(IntPtr handle,out FI info);
 readonly DesktopTrustKeyRootSource root;static readonly byte[] Entropy=Encoding.UTF8.GetBytes("ANVIL-V3:DESKTOP-TRUST-BINDINGS:V1");
 internal WindowsDesktopTrustKeyBindingKernel(DesktopTrustKeyRootSource value){root=value;}
 string PathFor(string name){if(!new[]{"bindings.v1","bindings.v1.previous","bindings.v1.next","bindings.v1.lock"}.Contains(name))throw DesktopTrustKeyParentBasisSource.Invalid();root.Check();return Path.Combine(root.PathValue,name);}
