 internal override byte[] Read(string name,int maximum){string path=PathFor(name);try{FileShape(path);}catch(FileNotFoundException){return null;}using(var file=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.None)){if(file.Length<1||file.Length>maximum)throw DesktopTrustKeyParentBasisSource.Invalid();byte[] b=new byte[(int)file.Length];int at=0,n;while(at<b.Length&&(n=file.Read(b,at,b.Length-at))>0){at+=n;root.Check();}if(at!=b.Length)throw DesktopTrustKeyParentBasisSource.Invalid();FileShape(path,file);return b;}}
 internal override IDisposable Lock(){return new FileStream(PathFor("bindings.v1.lock"),FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None,4096,FileOptions.DeleteOnClose);}
 internal override void WriteNext(byte[] bytes){string path=PathFor("bindings.v1.next");using(var file=new FileStream(path,FileMode.CreateNew,FileAccess.ReadWrite,FileShare.None)){file.Write(bytes,0,bytes.Length);file.Flush(true);root.Check();if(file.Length!=bytes.Length)throw DesktopTrustKeyParentBasisSource.Invalid();file.Position=0;for(int i=0;i<bytes.Length;i++)if(file.ReadByte()!=bytes[i])throw DesktopTrustKeyParentBasisSource.Invalid();}FileShape(path);}
